function fact(n){ var f=1; for(var i=2;i<=n;i++) f*=i; return f; }
function rank(perm){ var n=perm.length, r=0; for(var i=0;i<n;i++){ var smaller=0; for(var j=i+1;j<n;j++){ if(perm[j]<perm[i]) smaller++; } r += smaller*fact(n-1-i); } return r; }
function unrank(n, k){ var nums=[]; for(var i=0;i<n;i++) nums.push(i); var r=k, perm=[];
  for(var pos=0;pos<n;pos++){ var f=fact(n-1-pos); var idx=Math.floor(r/f); perm.push(nums[idx]); nums.splice(idx,1); r=r-f*idx; } return perm; }
var EXPORTS={fact:fact, rank:rank, unrank:unrank};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PermutationRankForgePure = EXPORTS; }
